using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class SpatialDetailRefresh {public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var r=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform.Find("B5_Spatial_Refinement");var names=new[]{"LivingBed","MedicalBed","TwinCoolingPump","ExpansionVessel","PlateHeatExchanger","ValveManifold"};foreach(string n in names)AssetDatabase.ImportAsset("Assets/Afrer_Seconds/05.Model/Props/B5/SF_"+n+".fbx",ImportAssetOptions.ForceUpdate|ImportAssetOptions.ForceSynchronousImport);foreach(var f in r.GetComponentsInChildren<MeshFilter>()){if(!names.Any(n=>f.name.Contains(n)))continue;var mc=f.GetComponent<MeshCollider>();if(mc)mc.sharedMesh=f.sharedMesh;var bc=f.GetComponent<BoxCollider>();if(bc){bc.center=f.sharedMesh.bounds.center;bc.size=f.sharedMesh.bounds.size;}PrefabUtility.RecordPrefabInstancePropertyModifications(f.transform);foreach(var rr in f.GetComponents<Renderer>())PrefabUtility.RecordPrefabInstancePropertyModifications(rr);}Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{refreshed=names.Length};}}
